import{prepare,ready}from'./browser.js';import{commerceFixture,owner}from'./commerce.js';
export const day='2026-10-29';
export const records=Array.from({length:11},(_,i)=>({id:String(i+1),name:'Cliente '+(i+1),address:'Rua de teste, '+(i+1)+', Natal, RN',city:'Natal',state:'RN',priority:2,lat:i===10?null:-5.80-i*.001,lon:i===10?null:-35.21,locationVerification:i===9?'unverified':'manual_reviewed',...(i===9?{}:{locationConfirmedAt:'2026-10-01T12:00:00Z'})}));
export const visits=[[1,25],[2,28],[3,29],[4,27],[5,26],[6,25],[7,28],[8,24],[1,29],[2,29],[3,29]].map(([id,date],i)=>({id:'40000000-0000-4000-8000-'+String(i+1).padStart(12,'0'),clientId:String(id),client:{id:String(id),name:'Cliente '+id,address:records[id-1].address,city:'Natal'},visitDate:'2026-10-'+date,status:'confirmed',source:'manual_entry',recordedAt:'2026-10-'+date+'T'+String(i+8).padStart(2,'0')+':00:00Z',routeId:'execution-'+date}));
export async function detailsSetup(page){await page.clock.setFixedTime(new Date('2026-10-29T15:00:00Z'));await prepare(page,{records,lockAuthFixture:true});await commerceFixture(page);if(process.env.TRAXELO_PWA_BASE)await page.route(process.env.TRAXELO_PWA_BASE+'/**',r=>r.continue());await ready(page);await page.waitForFunction(()=>!!TraxeloVisits?.getStore()&&!!RotaMapaSales?.getStore());await page.evaluate(visits=>{for(const v of visits)TraxeloVisits.getStore().add(v);document.getElementById('visitTimeZone').value='America/Fortaleza';document.getElementById('visitReportMonth').value='2026-10';TraxeloVisits.render();},visits);await page.locator('[data-tab=historico]').click();}
